sketch:
// LED bar — five LEDs in one package.
//
// Each anode is a digital pin and the matching cathode goes to GND. The
// sketch fills the bar one LED at a time, then empties it.

void setup() {
  for (int pin = 2; pin <= 6; pin++) pinMode(pin, OUTPUT);
}

void loop() {
  for (int pin = 2; pin <= 6; pin++) {
    digitalWrite(pin, HIGH);
    delay(150);
  }
  for (int pin = 2; pin <= 6; pin++) {
    digitalWrite(pin, LOW);
    delay(150);
  }
}
